import {supabase,currentUser} from './auth-client.mjs';
const demoKey='album-trade-preferences-preview-v1',signal='album-trade-preferences-changed';
import {defaultPreferences,preferencePatch} from './exchange-preferences-model.mjs';
export {defaultPreferences,preferencePatch};
export async function readTradePreferences(season,preview=false){if(preview){try{return {...defaultPreferences,...JSON.parse(localStorage.getItem(demoKey)||'{}')}}catch{return {...defaultPreferences}}}const actor=await currentUser();if(!actor)throw Error('Log in to change your trade settings.');const {data,error}=await supabase.from('album_trade_preferences').select('rarity_mode,trades_left_today').eq('user_id',actor.id).eq('season_id',season).maybeSingle();if(error)throw error;if((await currentUser())?.id!==actor.id)throw Error('Your account changed.');return {...defaultPreferences,...data}}
export async function writeTradePreferences(season,patch,preview=false){const clean=preferencePatch(patch);if(preview){const row={...await readTradePreferences(season,true),...clean};localStorage.setItem(demoKey,JSON.stringify(row));window.dispatchEvent(new Event(signal));return row}const actor=await currentUser();if(!actor)throw Error('Please log in again.');const result=await supabase.from('album_trade_preferences').update(clean).eq('user_id',actor.id).eq('season_id',season).select('user_id');if(result.error)throw result.error;if(!result.data?.length){const {error}=await supabase.from('album_trade_preferences').insert({user_id:actor.id,season_id:season,...preferencePatch(defaultPreferences),...clean});if(error)throw error}if((await currentUser())?.id!==actor.id)throw Error('Your account changed.');try{localStorage.setItem(signal,String(Date.now()))}catch{}window.dispatchEvent(new Event(signal));return readTradePreferences(season)}
export function watchTradePreferences(callback){window.addEventListener('storage',e=>{if([signal,demoKey].includes(e.key))callback()});window.addEventListener('focus',callback);window.addEventListener(signal,callback)}
